CREATE TABLE IF NOT EXISTS gis_spatial_comparison_details (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, comparison_dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, run_reference text NOT NULL, primary_feature_code text NOT NULL, comparison_feature_code text, primary_name text, comparison_name text, code_match boolean NOT NULL DEFAULT false, name_match boolean NOT NULL DEFAULT false, geometry_match boolean NOT NULL DEFAULT false, area_difference_pct numeric, bbox_overlap_pct numeric, status text NOT NULL DEFAULT 'Review', discrepancy_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_spatial_comparison_details_run ON gis_spatial_comparison_details(run_reference,status);
CREATE INDEX IF NOT EXISTS idx_gis_spatial_comparison_details_codes ON gis_spatial_comparison_details(primary_feature_code,comparison_feature_code);